<?php
namespace App\Http\Controllers;
use App\Models\Admin;use App\Models\Store;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Uploadcare\Api;use Uploadcare\Configuration;
class HouseStoreController extends Controller {
 public function show(Request $r):JsonResponse{$this->auth($r);return response()->json($this->shape(Store::primary()??Store::firstOrCreate(['setup_key'=>Store::PRIMARY_KEY],['name'=>config('app.name')])));}
 public function save(Request $r):JsonResponse{$this->auth($r);$d=$r->validate(['store_name'=>['required','string','max:255'],'sku_prefix'=>['required','regex:/^[A-Za-z0-9]{4}$/'],'email'=>['required','email','max:255'],'phone'=>['required','regex:/^01[3-9][0-9]{8}$/'],'address_line'=>['required','string','max:255'],'address_area'=>['required','string','max:255'],'address_district'=>['required','string','max:255'],'store_logo'=>['nullable','file','image','max:5120'],'clear_store_logo'=>['sometimes','boolean']]);$store=Store::firstOrCreate(['setup_key'=>Store::PRIMARY_KEY],['name'=>config('app.name')]);$logo=$r->boolean('clear_store_logo')?null:$store->logo;if($r->hasFile('store_logo')){$api=new Api(Configuration::create(config('services.uploadcare.public_key'),config('services.uploadcare.secret_key')));$logo='https://ucarecdn.com/'.$api->uploader()->fromPath($r->file('store_logo')->getPathname())->getUuid().'/-/preview/';}$store->update(['name'=>trim($d['store_name']),'sku_prefix'=>strtoupper($d['sku_prefix']),'support_email'=>$d['email'],'support_phone'=>$d['phone'],'address_line'=>$d['address_line'],'address_area'=>$d['address_area'],'address_district'=>$d['address_district'],'store_address'=>implode(', ',[$d['address_line'],$d['address_area'],$d['address_district']]),'logo'=>$logo]);return response()->json($this->shape($store->fresh()));}
 private function shape(Store $s):array{return ['store_name'=>$s->name,'store_logo'=>$s->logo,'email'=>$s->support_email,'phone'=>$s->support_phone,'address_line'=>$s->address_line,'address_area'=>$s->address_area,'address_district'=>$s->address_district,'sku_prefix'=>$s->sku_prefix,'joined_at'=>$s->created_at?->toDateString()];}
 private function auth(Request $r):void{$a=$r->user();abort_unless($a instanceof Admin&&$a->role==='super_admin',403);}
}
